components.css:
.ds-card{background:#161B18;border:1px solid rgba(216,203,170,.22);border-radius:7px;padding:10px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;color:#D8CBAA;max-width:320px}
.ds-card-top{display:flex;align-items:flex-start;gap:8px}
.ds-card-mark{width:22px;height:22px;border-radius:4px;flex:0 0 auto;background:#6E8C4B}
.ds-card-col{flex:1;min-width:0}
.ds-card-t{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ds-card-m{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace;font-size:9.5px;color:rgba(216,203,170,.72);letter-spacing:.06em;margin-top:3px}
.ds-card-acts{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px}
.ds-cbtn{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;font-size:9px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;padding:6px 9px;min-height:36px;min-width:36px;border-radius:6px;border:1px solid rgba(216,203,170,.48);background:transparent;color:#D8CBAA;cursor:pointer;flex:0 0 auto;touch-action:manipulation}
.ds-cbtn-primary{background:#CC5A2E;border-color:#CC5A2E;color:#12100E}
.ds-cbtn:active{filter:brightness(1.25)}
.ds-cbtn:focus-visible{outline:2px solid #DC8767;outline-offset:2px}
.ds-del{margin-left:auto}

.ds-statsbar{display:flex;height:56px;background:linear-gradient(180deg,#111513 0,#111513 calc(100% - 3px),#1B221D calc(100% - 3px),#333D36 100%);box-shadow:0 1px 0 rgba(0,0,0,.65),0 6px 12px -6px rgba(0,0,0,.55);max-width:360px}
.ds-stat{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:0 2px;border-right:1px solid rgba(216,203,170,.22);border-image:linear-gradient(180deg,rgba(216,203,170,.22) calc(100% - 3px),transparent 0) 1}
.ds-stat:last-child{border-right:none}
.ds-lbl{display:block;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;font-size:8.5px;letter-spacing:.14em;color:#FFFFFF;text-transform:uppercase}
.ds-stat b{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace;font-size:17px;font-weight:600;line-height:1.05;color:#FFFFFF;white-space:nowrap}
.ds-stat b em{font-style:normal;color:#FFFFFF;letter-spacing:.04em;margin-right:5px}
.ds-stat i{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;font-size:8px;font-style:normal;letter-spacing:.12em;color:#FFFFFF;text-transform:uppercase}
